// ===== Bar.qml =====
pragma ComponentBehavior: Bound

import Quickshell
import Quickshell.Wayland
import Quickshell.Hyprland
import Quickshell.Services.Pipewire
import Quickshell.Services.UPower
import Quickshell.Services.Mpris
import Quickshell.Services.SystemTray
import Quickshell.Widgets
import QtQuick
import QtQuick.Layouts

Scope {
    // Bind the default sink so .audio.volume / .muted are populated
    PwObjectTracker { objects: [ Pipewire.defaultAudioSink ] }

    Variants {
        model: Quickshell.screens

        PanelWindow {
            id: bar
            required property ShellScreen modelData
            screen: modelData

            WlrLayershell.namespace: "cutebar"   // target for hl.layer_rule
            anchors { top: true; left: true; right: true }
            margins { top: 6; left: 8; right: 8 }
            implicitHeight: 36
            color: "transparent"                 // QsWindow.color defaults to white

            readonly property HyprlandMonitor monitor: Hyprland.monitorFor(modelData)
            readonly property MprisPlayer player:
                Mpris.players.values.find(p => p.isPlaying) ?? Mpris.players.values[0] ?? null

            Rectangle {
                anchors.fill: parent
                radius: height / 2
                color: "#cc1e1e2e"

                RowLayout {
                    anchors { fill: parent; leftMargin: 12; rightMargin: 12 }
                    spacing: 10

                    // Workspaces on this monitor; the active pill springs wider
                    Repeater {
                        model: Hyprland.workspaces
                        delegate: Rectangle {
                            id: ws
                            required property HyprlandWorkspace modelData
                            visible: modelData.id > 0 && modelData.monitor === bar.monitor
                            implicitWidth: modelData.active ? 26 : 10
                            implicitHeight: 10
                            radius: 5
                            color: modelData.active ? "#f5c2e7" : (modelData.urgent ? "#f38ba8" : "#6c7086")
                            Behavior on implicitWidth { NumberAnimation { duration: 280; easing.type: Easing.OutBack } }
                            Behavior on color { ColorAnimation { duration: 200 } }
                            MouseArea {
                                anchors.fill: parent
                                onClicked: ws.modelData.activate() // Lua-aware in Quickshell 0.3.x
                            }
                        }
                    }

                    Item { Layout.fillWidth: true }

                    Text {
                        visible: bar.player !== null
                        text: bar.player ? `${bar.player.trackArtist} - ${bar.player.trackTitle}` : ""
                        color: "#cdd6f4"
                        elide: Text.ElideRight
                        Layout.maximumWidth: 300
                        MouseArea { anchors.fill: parent; onClicked: bar.player?.togglePlaying() }
                    }

                    Text { text: Time.time; color: "#cdd6f4"; font.bold: true }

                    Item { Layout.fillWidth: true }

                    Text {
                        id: volText
                        readonly property var audio: Pipewire.defaultAudioSink?.audio ?? null
                        text: audio ? (audio.muted ? "muted" : `vol ${Math.round(audio.volume * 100)}%`) : "no audio"
                        color: "#cdd6f4"
                        MouseArea {
                            anchors.fill: parent
                            onClicked: if (volText.audio) volText.audio.muted = !volText.audio.muted
                            onWheel: wheel => {
                                if (!volText.audio) return;
                                const step = wheel.angleDelta.y > 0 ? 0.05 : -0.05;
                                volText.audio.volume = Math.max(0, Math.min(1, volText.audio.volume + step));
                            }
                        }
                    }

                    Text {
                        visible: UPower.displayDevice.isLaptopBattery
                        text: `bat ${Math.round(UPower.displayDevice.percentage * 100)}%` // percentage is 0-1
                        color: UPower.onBattery ? "#fab387" : "#a6e3a1"
                    }

                    Repeater {
                        model: SystemTray.items
                        delegate: MouseArea {
                            id: trayItem
                            required property SystemTrayItem modelData
                            implicitWidth: 18
                            implicitHeight: 18
                            acceptedButtons: Qt.LeftButton | Qt.RightButton | Qt.MiddleButton
                            onClicked: mouse => {
                                if (mouse.button === Qt.LeftButton) modelData.activate();
                                else if (mouse.button === Qt.MiddleButton) modelData.secondaryActivate();
                                else if (modelData.hasMenu) {
                                    const p = bar.itemPosition(trayItem);
                                    modelData.display(bar, p.x, p.y + trayItem.height);
                                }
                            }
                            IconImage { anchors.fill: parent; source: trayItem.modelData.icon }
                        }
                    }
                }
            }
        }
    }
}

