import Quickshell
import Quickshell.Wayland

ShellRoot {
	LockContext {
		id: lockContext
		onUnlocked: {
			// Unlock the screen before exiting, or the compositor will display a
			// fallback lock you can't interact with.
			lock.locked = false;
			Qt.quit();
		}
	}

	WlSessionLock {
		id: lock
		locked: true

		WlSessionLockSurface {
			LockSurface {
				anchors.fill: parent
				context: lockContext
			}
		}
	}
}

