{
  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";   # or nixos-26.05 (then HM release-26.05)
    home-manager = {
      url = "github:nix-community/home-manager";          # master tracks 26.11
      inputs.nixpkgs.follows = "nixpkgs";
    };
    nixos-hardware.url = "github:NixOS/nixos-hardware";
    nix-index-database = {
      url = "github:nix-community/nix-index-database";
      inputs.nixpkgs.follows = "nixpkgs";
    };
  };

  outputs = { self, nixpkgs, home-manager, ... }@inputs:
    let
      user = "me";
      mkHost = { hostname, extraModules ? [ ] }:
        nixpkgs.lib.nixosSystem {
          # no `system =`: legacy alias; hardware-configuration.nix sets nixpkgs.hostPlatform
          specialArgs = { inherit inputs self hostname user; };
          modules = [
            ./hosts/${hostname}          # default.nix imports ./hardware-configuration.nix
            ./modules/nixos
            {
              networking.hostName = hostname;
              nixpkgs.overlays = [ self.overlays.default ];
              nixpkgs.config.allowUnfree = true;
            }
            inputs.nix-index-database.nixosModules.default
            home-manager.nixosModules.home-manager
            {
              home-manager = {
                useGlobalPkgs = true;       # HM reuses system pkgs/overlays
                useUserPackages = true;
                backupFileExtension = "hm-bak";
                extraSpecialArgs = { inherit inputs self hostname user; };
                users.${user} = ./home;
              };
            }
          ] ++ extraModules;
        };
    in {
      overlays.default = import ./overlays { inherit inputs; };

      nixosConfigurations = {
        desktop = mkHost { hostname = "desktop"; extraModules = [ ./modules/nixos/nvidia.nix ]; };
        laptop  = mkHost { hostname = "laptop";
                           extraModules = [ inputs.nixos-hardware.nixosModules.common-pc-laptop-ssd ]; };
      };

      # optional: same ./home on Arch via standalone HM (`nh home switch . -c me@arch`)
      homeConfigurations."me@arch" = home-manager.lib.homeManagerConfiguration {
        pkgs = nixpkgs.legacyPackages.x86_64-linux;
        extraSpecialArgs = { inherit inputs self; hostname = "arch"; user = "me"; };
        modules = [ ./home { targets.genericLinux.enable = true; } ];
      };
    };
}

