# flake.nix
{
  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
    flake-parts = { url = "github:hercules-ci/flake-parts"; inputs.nixpkgs-lib.follows = "nixpkgs"; };
    # ...other inputs
  };
  outputs = inputs@{ flake-parts, ... }:
    flake-parts.lib.mkFlake { inherit inputs; } {
      systems = [ "x86_64-linux" ];
      imports = [ ./hosts ./modules ];   # each file sets e.g. flake.nixosConfigurations = { ... };
      perSystem = { pkgs, ... }: {
        formatter = pkgs.nixfmt;
        devShells.default = pkgs.mkShell { packages = [ pkgs.git pkgs.nh ]; };
      };
    };
}

# home/dotfiles.nix
{ config, lib, ... }:
let
  # MUST be an absolute STRING. A ./path would resolve into the flake's /nix/store copy (HM #2085/#2660).
  dots = "${config.home.homeDirectory}/dotfiles/config";
  link = app: config.lib.file.mkOutOfStoreSymlink "${dots}/${app}";
in {
  # ~/.config/<app> -> ~/dotfiles/config/<app>  (one symlink per dir; recursive = false is the default)
  xdg.configFile = lib.genAttrs [ "hypr" "quickshell" "matugen" "kitty" "uwsm" "fuzzel" ] (app: {
    source = link app;
  });

  # Do NOT also enable HM modules that write into these dirs, e.g.
  #   wayland.windowManager.hyprland.enable  (writes hypr/hyprland.lua + hypr/.luarc.json)
  #   programs.kitty.settings / programs.quickshell.configs
  # -> 'Conflicting managed target files' or files written into your repo.
}

