#!/usr/bin/env bash
set -Eeuo pipefail
shopt -s inherit_errexit

readonly SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
readonly RUN_ID="$(date +%Y%m%d-%H%M%S)"
readonly STATE_DIR="${XDG_STATE_HOME:-$HOME/.local/state}/rice-install"
readonly BACKUP_DIR="$STATE_DIR/backups/$RUN_ID"
readonly LOG_FILE="$STATE_DIR/logs/$RUN_ID.log"
DRY_RUN=0; ASSUME_YES=0; AUR_HELPER="${AUR_HELPER:-yay}"

mkdir -p -- "$STATE_DIR/logs"
exec > >(tee -a -- "$LOG_FILE") 2>&1
trap 'rc=$?; printf "FAILED rc=%d at %s:%d: %s\n" "$rc" "${BASH_SOURCE[0]}" "$LINENO" "$BASH_COMMAND" >&2; exit "$rc"' ERR

while (($#)); do
  case $1 in
    -n|--dry-run) DRY_RUN=1 ;;
    -y|--yes) ASSUME_YES=1 ;;
    --aur-helper) AUR_HELPER=${2:?}; shift ;;
    -h|--help) echo "usage: ${0##*/} [--dry-run] [--yes] [--aur-helper yay|paru]"; exit 0 ;;
    *) echo "unknown arg: $1" >&2; exit 2 ;;
  esac; shift
done

((EUID != 0)) || { echo 'run as your normal user (makepkg refuses root)' >&2; exit 1; }

log()     { printf '[%(%T)T] %s\n' -1 "$*"; }
run()     { if ((DRY_RUN)); then printf '[dry-run]'; printf ' %q' "$@"; printf '\n'; else "$@"; fi; }
confirm() { ((ASSUME_YES)) && return 0
            if [[ -t 0 ]] && command -v gum >/dev/null; then gum confirm "$1"
            else local a; read -r -p "$1 [y/N] " a; [[ $a == [yY]* ]]; fi; }
list()    { grep -Ev '^[[:space:]]*(#|$)' -- "$1"; }

install_repo_pkgs() {
  local -a pkgs; mapfile -t pkgs < <(list "$SCRIPT_DIR/packages/repo.txt")
  pacman -Si -- "${pkgs[@]}" >/dev/null            # fail fast on renamed/removed names (swww, nvidia-dkms...)
  run sudo pacman -Syu --needed --noconfirm -- "${pkgs[@]}"   # ONE full-upgrade transaction; never -Sy <pkg>
}

ensure_aur_helper() {
  command -v "$AUR_HELPER" >/dev/null && return 0
  local pkg tmp; pkg=$([[ $AUR_HELPER == yay ]] && echo yay-bin || echo paru)   # paru-bin is orphaned
  tmp=$(mktemp -d); trap 'rm -rf -- "$tmp"' RETURN
  run git clone --depth=1 "https://aur.archlinux.org/$pkg.git" "$tmp/$pkg"
  (cd -- "$tmp/$pkg" && run makepkg -si --noconfirm)
}

install_aur_pkgs() {
  local -a pkgs; mapfile -t pkgs < <(list "$SCRIPT_DIR/packages/aur.txt")
  ((${#pkgs[@]})) || return 0
  run "$AUR_HELPER" -S --needed -- "${pkgs[@]}"      # keep PKGBUILD review interactive
}

link() {  # link <repo-src> <target>: re-runnable, backs up anything that is not already our link
  local src=$1 dst=$2
  [[ -L $dst && $(readlink -- "$dst") == "$src" ]] && return 0
  if [[ -e $dst || -L $dst ]]; then
    run mkdir -p -- "$BACKUP_DIR/$(dirname -- "${dst#"$HOME"/}")"
    run mv -- "$dst" "$BACKUP_DIR/${dst#"$HOME"/}"
  fi
  run mkdir -p -- "$(dirname -- "$dst")"
  run ln -s -- "$src" "$dst"
}

main() {
  log "log=$LOG_FILE backups=$BACKUP_DIR dry_run=$DRY_RUN"
  confirm 'Install packages and link dotfiles?' || exit 0
  install_repo_pkgs
  ensure_aur_helper
  install_aur_pkgs
  link "$SCRIPT_DIR/home/hypr/.config/hypr" "$HOME/.config/hypr"
  log 'done'
}
main "$@"

findings.detail:
The fork is FrancescoCaracciolo/material-you-colors (GPL-3.0), itself a fork of avanisubbiah/material-you-theme. It generates, from the wallpaper or a chosen accent:
- a libadwaita CSS in ~/.config/gtk-4.0/gtk.css (the marker file .materialyou contains 'yes');
- GTK3 colors through adw-gtk3;
- a GNOME Shell 'MaterialYou' theme (built with sass and applied with user-theme);
- pywal colors (enable-pywal-theming=true);
- ArcMenu theming.

Its extra-command runs 'bash ~/.config/nyarch/after_wp_change.sh &'. That script reads accent_bg_color (dark mode) or accent_color (light mode) from gtk-4.0/gtk.css. It then runs the Nyarch Tela-circle fork's install.sh -n Tela-circle-MaterialYou <hex> and sets icon-theme to Tela-circle-MaterialYou-<hex>, so the icons follow the wallpaper color.

A global Flatpak override exposes xdg-config/gtk-3.0 and gtk-4.0 so Flatpak apps pick up the theme. The website describes it as: 'Choose any waifu as your wallpaper, the desktop and applications themes will automatically adapt their colors'.

